+      title: 'Catalog Search',
+      description:
+        'Search catalog items by name (case-insensitive partial match) with ' +
+        'offset/limit pagination. Returns matching rows and next_offset when ' +
+        'more results exist.\n\n' +
+        'Args:\n' +
+        '  - query (string, required): substring to match against item names\n' +
+        '  - offset (integer, default 0): number of matches to skip\n' +
+        '  - limit (integer, default 2, range 1-5): max rows to return\n\n' +
+        'Returns a text summary of matching rows plus next_offset when more ' +
+        'results remain.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          query: { type: 'string', description: 'Substring to match against item names (case-insensitive)' },
+          offset: { type: 'integer', minimum: 0, default: 0, description: 'Number of matches to skip' },
+          limit: { type: 'integer', minimum: MIN_LIMIT, maximum: MAX_LIMIT, default: DEFAULT_LIMIT, description: 'Max rows to return (1-5)' }
+        },
+        required: ['query'],
+        additionalProperties: false
+      },
+      annotations: {
+        readOnlyHint: true,
+        destructiveHint: false,
+        idempotentHint: true,
+        openWorldHint: false
+      }
+    }
+  ];
+}
+
+function isInteger(v) {
+  return typeof v === 'number' && Number.isInteger(v);
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== TOOL_NAME) {
+    const error = new Error(`Unknown tool: ${name}`);
+    error.code = -32601;
+    throw error;
+  }
+
+  // Validate required query
+  if (typeof args.query !== 'string') {
+    const error = new Error("'query' is required and must be a string");
+    error.code = -32602;
+    throw error;
+  }
+
+  // Validate offset (default 0)
+  let offset = 0;
+  if (args.offset !== undefined) {
+    if (!isInteger(args.offset) || args.offset < 0) {
+      const error = new Error("'offset' must be a non-negative integer");
+      error.code = -32602;
+      throw error;
+    }
+    offset = args.offset;
+  }
+
+  // Validate limit (default 2, range 1-5)
+  let limit = DEFAULT_LIMIT;
+  if (args.limit !== undefined) {
+    if (!isInteger(args.limit) || args.limit < MIN_LIMIT || args.limit > MAX_LIMIT) {
+      const error = new Error(`'limit' must be an integer between ${MIN_LIMIT} and ${MAX_LIMIT}`);
+      error.code = -32602;
+      throw error;
+    }
