+    content: [{ type: 'text', text: lines.join('\n') }],
+    structuredContent: {
+      query: args.query,
+      offset,
+      limit,
+      count: page.length,
+      total: matches.length,
+      items: page,
+      has_more: hasMore,
+      ...(nextOffset !== null ? { next_offset: nextOffset } : {})
+    }
+  };
+}
